pub fn maybeReportError(self: *@This(), comptime fmt: []const u8, args: anytype) void {
            _ = (blk_catch_0: { break :blk_catch_0 ((self.log.addErrorFmt(null, logger.Loc.Empty, self.allocator, fmt, args)) catch |__ce_0| { _ = &__ce_0; _ = 0; }); });
    }

pub fn buf(self: @This()) []const u8 {
            return self.lockfile.buffers.string_bytes.items;
    }

pub fn packageName(self: *@This(), id: PackageID) String.Formatter {
            return self.lockfile.packages.items(.name)[@as(usize, @intCast(id))].fmt(self.lockfile.buffers.string_bytes.items);
    }

pub fn packageVersion(self: *@This(), id: PackageID) Resolution.Formatter {
            return self.lockfile.packages.items(.resolution)[@as(usize, @intCast(id))].fmt(self.lockfile.buffers.string_bytes.items, .auto);
    }

pub fn clean(self: *@This()) OOM!CleanResult {
            var total: u32 = 0;
            _ = &total;
            const list_ptr = self.list.bytes;
            const slice = self.list.toOwnedSlice();
            var trees = slice.items(.tree);
            _ = &trees;
            const dependencies = slice.items(.dependencies);
            for (cp_iter_slice(trees)) |tree| {
                _ = &tree;
                total = (total + tree.dependencies.len);
            }
            var dep_ids = try DependencyIDList.initCapacity(self.allocator, total);
            _ = &dep_ids;
            var i: usize = 0;
            _ = &i;
            while ((i < trees.len)) : (i = (i + 1)) {
                const tree = (&trees[@as(usize, @intCast(i))]);
                const child = (&dependencies[@as(usize, @intCast(i))]);
                defer {
                _ = child.deinit(self.allocator);
                }
                const off: u32 = @intCast(dep_ids.items.len);
                for (child.items) |dep_id| {
                    _ = &dep_id;
                    const pkg_id = self.lockfile.buffers.resolutions.items[@as(usize, @intCast(dep_id))];
                    if ((pkg_id == invalid_package_id)) {
                        continue;
                    }
                    _ = dep_ids.appendAssumeCapacity(dep_id);
                }
                const len: u32 = @intCast((dep_ids.items.len - off));
                tree.dependencies.off = off;
                tree.dependencies.len = len;
            }
            _ = self.queue.deinit();
            _ = self.sort_buf.deinit(self.allocator);
            _ = self.pending_optional_peers.deinit();
            if ((@intFromPtr(trees.ptr) != @intFromPtr(list_ptr))) {
                var new: [*]Tree = @ptrCast(list_ptr);
                _ = &new;
            }
            return .{ .trees = std.ArrayListUnmanaged(Tree).fromOwnedSlice(trees), .dep_ids = dep_ids };
    }
    pub const Entry = struct {
        tree: Tree,
        dependencies: Lockfile.DependencyIDList,
    };
    pub const CleanResult = struct {
        trees: std.ArrayListUnmanaged(Tree),
        dep_ids: std.ArrayListUnmanaged(DependencyID),
    };
};
}

pub fn isFilteredDependencyOrWorkspace(dep_id: DependencyID, parent_pkg_id: PackageID, workspace_filters: []const WorkspaceFilter, install_root_dependencies: bool, manager: *const PackageManager, lockfile: *const Lockfile) bool {
        const pkg_id = lockfile.buffers.resolutions.items[@as(usize, @intCast(dep_id))];
        if ((pkg_id >= lockfile.packages.len)) {
            return false;
        }
        const pkg = lockfile.packages.get(pkg_id);
        const res = pkg.resolution;
        if (((manager.subcommand != .install) or (parent_pkg_id != 0))) {
            if ((res.tag == .workspace)) {
                return false;
            }
        }
        if (((res.tag != .workspace) and (!install_root_dependencies))) {
            return true;
        }
        if ((workspace_filters.len == 0)) {
            return false;
        }
        const pkg_names = lockfile.packages.items(.name);
        var workspace_matched = false;
        _ = &workspace_matched;
        for (cp_iter_slice(workspace_filters)) |filter| {
            _ = &filter;
            var filter_path: bun.AbsPath(.{.sep=.posix}) = .initTopLevelDir();
            _ = &filter_path;
            defer {
            _ = filter_path.deinit();
            }
            const filter_pair: [2][]const u8 = (switch (filter) {
.all => {
{
                workspace_matched = true;
                continue;
            }
},
.name => |name_pattern| .{ name_pattern, pkg_names[@as(usize, @intCast(pkg_id))].slice(lockfile.buffers.string_bytes.items) },
.path => |path_pattern| path_pattern_blk: {
            if ((res.tag != .workspace)) {
                return false;
            }
            _ = filter_path.join((&.{ (if (@typeInfo(@TypeOf(res)) == .@"enum") @intFromEnum(res) else res.value).workspace.slice(lockfile.buffers.string_bytes.items) }));
            break :path_pattern_blk .{ path_pattern, filter_path.slice() };
},
});
            const pattern = filter_pair[0];
            const name_or_path = filter_pair[1];
            switch (bun.glob.match(pattern, name_or_path)) {
.match, .negate_match => {
workspace_matched = true;
},
.negate_no_match => {
workspace_matched = false;
            break;
},
.no_match => {

},
}
        }
        return (!workspace_matched);
}
